import { themeVars } from "@/components/cursare/foundation/model/learner-runtime"
import { ContentCoverMedia, LearnerRoot } from "@/components/cursare/foundation/runtime"
import { Avatar, AvatarFallback, AvatarImage } from "@/components/cursare/ui/avatar"
import { Button } from "@/components/cursare/ui/button"
import { ArrowRight, CircleCheck, Star } from "lucide-react"
import type { CSSProperties, ReactNode } from "react"

const FALLBACK_COLOR_KEYS = [
  "amber",
  "orange",
  "rose",
  "red",
  "violet",
  "blue",
  "cyan",
  "emerald",
  "lime",
  "zinc",
] as const

export type FallbackColor = (typeof FALLBACK_COLOR_KEYS)[number]

export const FALLBACK_TINTS: Record<FallbackColor, string> = {
  amber: "var(--warning)",
  orange: "var(--fx-a, var(--primary))",
  rose: "var(--fx-b, var(--primary))",
  red: "var(--destructive)",
  violet: "var(--fx-c, var(--primary))",
  blue: "var(--primary)",
  cyan: "var(--chart-2, var(--primary))",
  emerald: "var(--success)",
  lime: "var(--chart-4, var(--primary))",
  zinc: "var(--muted-foreground)",
}

function fallbackColor(seed: string): FallbackColor {
  let hash = 0
  for (const char of seed.toLowerCase()) hash = (hash * 31 + char.charCodeAt(0)) % 997
  return FALLBACK_COLOR_KEYS[hash % FALLBACK_COLOR_KEYS.length] ?? "zinc"
}

// Stable for the same seed.
export function fallbackTint(seed: string): CSSProperties {
  return { "--fallback-tint": FALLBACK_TINTS[fallbackColor(seed)] } as CSSProperties
}

export function orgInitials(name: string): string {
  return (
    name
      .split(/[\s/]+/)
      .filter(Boolean)
      .slice(0, 2)
      .map((word) => word[0] ?? "")
      .join("")
      .toUpperCase() || "•"
  )
}

export function OrgAvatar({
  name,
  logo,
  className,
  fallbackClassName,
}: {
  name: string
  logo?: string | null
  className?: string
  fallbackClassName?: string
}) {
  return (
    <Avatar className={className}>
      {logo ? <AvatarImage src={logo} alt="" /> : null}
      <AvatarFallback
        className={`fallback-panel rounded-[inherit] font-heading font-semibold ${fallbackClassName ?? ""}`}
        style={fallbackTint(name)}
      >
        {orgInitials(name)}
      </AvatarFallback>
    </Avatar>
  )
}

export interface CourseHeroCardProps {
  coverImage: string | null
  title: string
  publisher: string
  publisherLogo?: string | null
  description: string | null
  tags?: string[]
  priceLabel?: string
  rating: { average: number; count: number } | null
  progress?: ReactNode
  cta: ReactNode
  badge?: ReactNode
  completed?: boolean
  orientation?: "vertical" | "horizontal"
  theme?: string | null
  className?: string
  showPublisher?: boolean
  contractKey?: "blocks.course-card" | "blocks.course-hero-card"
}

// All commercial copy is host-supplied.
export function CourseHeroCard({
  coverImage,
  title,
  publisher,
  publisherLogo = null,
  description,
  tags,
  priceLabel,
  rating,
  progress,
  cta,
  badge,
  completed = false,
  orientation = "vertical",
  theme,
  className,
  showPublisher = true,
  contractKey = "blocks.course-hero-card",
}: CourseHeroCardProps) {
  const isHorizontal = orientation === "horizontal"
  const resolvedTitle = title || "Untitled course"
  const coverClassName = isHorizontal ? "size-full" : "h-36 w-full"
  const cover = (
    <ContentCoverMedia src={coverImage} contentSlot="course-cover" className={coverClassName} />
  )

  return (
    <LearnerRoot
      contractKey={contractKey}
      data-learner-effect="lift"
      data-slot="course-hero-card"
      data-course-card-orientation={orientation}
      className={`learner-course-card relative w-full overflow-hidden ${isHorizontal ? "group flex flex-col p-3 sm:flex-row sm:items-center" : ""} ${className ?? ""}`}
      style={theme !== undefined ? themeVars(theme) : undefined}
    >
      {badge ? <div className="absolute end-3 top-3 z-10">{badge}</div> : null}
      {isHorizontal ? (
        <div
          data-course-cover-kind={coverImage ? "image" : "fallback"}
          className="learner-course-card-cover h-32 w-full shrink-0 overflow-hidden sm:size-24"
        >
          {cover}
        </div>
      ) : (
        cover
      )}
      <div
        data-slot="course-card-body"
        className={
          isHorizontal
            ? "flex min-w-0 flex-1 flex-col px-2 pt-4 pb-1 sm:grid sm:grid-cols-[minmax(0,1fr)_auto] sm:items-center sm:gap-6 sm:p-1 sm:pl-4"
            : "p-5"
        }
      >
        <div className="min-w-0">
          <h3
            data-slot="course-title"
            className={`flex items-center gap-1.5 font-heading font-semibold leading-tight tracking-tight ${isHorizontal ? "text-lg" : "text-xl"}`}
          >
            {completed ? (
              <CircleCheck className="size-4 shrink-0 text-emerald-600 dark:text-emerald-400" />
            ) : null}
            <span className={isHorizontal ? "line-clamp-2 break-words" : undefined}>
              {resolvedTitle}
            </span>
          </h3>
          {showPublisher ? (
            <div className="mt-1 flex items-center gap-1.5">
              <OrgAvatar
                name={publisher}
                logo={publisherLogo}
                className="size-4 shrink-0 rounded-full"
                fallbackClassName="text-[7px]"
              />
              <p className="text-muted-foreground text-xs">{publisher}</p>
            </div>
          ) : null}
          {description ? (
            <p
              className={`text-muted-foreground text-sm ${isHorizontal ? "mt-1 line-clamp-2" : "mt-3 line-clamp-3"}`}
            >
              {description}
            </p>
          ) : null}
          {tags && tags.length > 0 ? (
            <div
              className={`${isHorizontal ? "mt-2" : "mt-3"} flex flex-wrap items-center gap-x-2 gap-y-0.5`}
            >
              {tags.map((tag) => (
                <span key={tag} className="text-muted-foreground text-xs">
                  #{tag}
                </span>
              ))}
            </div>
          ) : null}
          {progress ? (
            <div className={isHorizontal ? "mt-2 inline-flex px-2 py-1" : "mt-4"}>{progress}</div>
          ) : null}
        </div>
        <div
          data-slot="course-card-footer"
          className={
            isHorizontal
              ? "mt-4 flex items-center justify-between gap-4 sm:mt-0 sm:flex-col sm:items-end"
              : "mt-5 flex items-center justify-between gap-4 border-t pt-4"
          }
        >
          <div className="flex items-center gap-2">
            {priceLabel ? <span className="font-medium text-sm">{priceLabel}</span> : null}
            {rating && rating.count > 0 ? (
              <span className="flex items-center gap-1 text-muted-foreground text-xs">
                <Star className="size-3 fill-current" aria-hidden />
                {rating.average.toFixed(1)} ({rating.count})
              </span>
            ) : null}
          </div>
          {cta}
        </div>
      </div>
    </LearnerRoot>
  )
}

export interface CourseCatalogItem {
  key: string
  href: string
  title: string
  publisher: string
  publisherLogo?: string | null
  description: string
  coverImage: string | null
  theme?: string | null
  tags?: string[]
  status?: "enrolled" | "completed"
  progressLabel?: string
  rating?: { average: number; count: number } | null
  priceLabel?: string
  ctaLabel: string
}

// Routing, money formatting and CTA copy belong to the host.
export function CourseCard({
  item,
  orientation,
  publisherContext = "show",
  onSelect,
}: {
  item: CourseCatalogItem
  orientation?: "vertical" | "horizontal"
  publisherContext?: "show" | "implicit"
  onSelect?: (item: CourseCatalogItem) => void
}) {
  return (
    <CourseHeroCard
      coverImage={item.coverImage}
      title={item.title}
      publisher={item.publisher}
      publisherLogo={item.publisherLogo ?? null}
      description={item.description}
      tags={publisherContext === "implicit" && item.status ? undefined : item.tags}
      priceLabel={item.priceLabel}
      rating={item.rating ?? null}
      orientation={orientation}
      theme={item.theme}
      completed={item.status === "completed"}
      showPublisher={publisherContext === "show"}
      contractKey="blocks.course-card"
      progress={
        item.progressLabel ? (
          <p className="text-muted-foreground text-xs">{item.progressLabel}</p>
        ) : undefined
      }
      cta={
        <Button
          variant={
            orientation === "horizontal"
              ? "secondary"
              : item.status === "enrolled"
                ? "default"
                : "outline"
          }
          className={
            orientation === "horizontal"
              ? "group/cta static after:absolute after:inset-0"
              : undefined
          }
          render={<a href={item.href} onClick={() => onSelect?.(item)} />}
        >
          {item.ctaLabel}
          {orientation === "horizontal" ? (
            <ArrowRight className="size-3.5 transition-transform group-hover/cta:translate-x-0.5" />
          ) : null}
        </Button>
      }
    />
  )
}

"use client"

import { LearnerRoot } from "@/components/cursare/foundation/runtime"
import { Input } from "@/components/cursare/ui/input"
import { Search } from "lucide-react"
import { useMemo, useState } from "react"
import { CourseCard, type CourseCatalogItem } from "./course-card"

export interface CourseCatalogProps {
  items: CourseCatalogItem[]
  id?: string
  heading?: string
  searchPlaceholder?: string
  emptyLabel?: string
  publisherContext?: "show" | "implicit"
  onSelect?: (item: CourseCatalogItem) => void
}

const SEARCH_MINIMUM_COURSES = 5

// Over data already resolved by the host.
export function CourseCatalog({
  items,
  id,
  heading,
  searchPlaceholder = "Search courses",
  emptyLabel = "No courses match your search.",
  publisherContext = "show",
  onSelect,
}: CourseCatalogProps) {
  const [query, setQuery] = useState("")
  const normalizedQuery = query.trim().toLowerCase()
  const shown = useMemo(
    () =>
      normalizedQuery
        ? items.filter(
            (item) =>
              item.title.toLowerCase().includes(normalizedQuery) ||
              item.description.toLowerCase().includes(normalizedQuery),
          )
        : items,
    [items, normalizedQuery],
  )

  const onlyItem = shown.length === 1 ? shown[0] : null
  const showSearch = items.length >= SEARCH_MINIMUM_COURSES

  return (
    <LearnerRoot
      as="section"
      contractKey="blocks.course-catalog"
      id={id}
      data-slot="course-catalog"
      className="scroll-mt-24 space-y-5"
    >
      {heading || showSearch ? (
        <div
          data-slot="course-catalog-toolbar"
          className="flex flex-wrap items-center justify-between gap-3"
        >
          {heading ? <h2 className="font-heading text-xl tracking-tight">{heading}</h2> : null}
          {showSearch ? (
            <div data-slot="course-catalog-search" className="relative ms-auto w-full max-w-xs">
              <Search className="-translate-y-1/2 pointer-events-none absolute top-1/2 left-3 size-4 text-muted-foreground" />
              <Input
                value={query}
                onChange={(event) => setQuery(event.target.value)}
                placeholder={searchPlaceholder}
                aria-label={searchPlaceholder}
                className="pl-9"
              />
            </div>
          ) : null}
        </div>
      ) : null}
      {shown.length === 0 ? (
        <p className="learner-course-empty p-8 text-center text-muted-foreground text-sm">
          {emptyLabel}
        </p>
      ) : onlyItem ? (
        <div
          data-slot="course-catalog-grid"
          data-catalog-layout="single"
          className="grid max-w-3xl"
        >
          <CourseCard
            item={onlyItem}
            orientation="horizontal"
            publisherContext={publisherContext}
            onSelect={onSelect}
          />
        </div>
      ) : shown.length <= 2 ? (
        <div data-slot="course-catalog-grid" className="grid max-w-4xl gap-4 sm:grid-cols-2">
          {shown.map((item) => (
            <CourseCard
              key={item.key}
              item={item}
              publisherContext={publisherContext}
              onSelect={onSelect}
            />
          ))}
        </div>
      ) : (
        <div data-slot="course-catalog-grid" className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
          {shown.map((item) => (
            <CourseCard
              key={item.key}
              item={item}
              publisherContext={publisherContext}
              onSelect={onSelect}
            />
          ))}
        </div>
      )}
    </LearnerRoot>
  )
}

/* Shared white-label surface styles. Brand comes exclusively from host tokens. */

.fallback-panel {
  background-color: color-mix(
    in oklab,
    var(--fallback-tint, var(--fx-a, var(--color-zinc-400))) 9%,
    var(--color-zinc-100)
  );
  background-image: radial-gradient(var(--color-border) 1px, transparent 1px);
  background-size: 20px 20px;
  color: var(--color-foreground);
}

.dark .fallback-panel {
  background-color: color-mix(
    in oklab,
    var(--fallback-tint, var(--fx-a, var(--color-zinc-400))) 12%,
    var(--color-zinc-900)
  );
}

.content-hero-page .content-prose .content-cover {
  display: none;
}

.learner-course-shell,
.learner-course-storefront {
  min-height: 100dvh;
}

.learner-course-shell {
  background: var(--background);
}

.learner-course-storefront {
  background: var(--course-canvas, var(--background));
}

.course-cover-theme {
  background: linear-gradient(
    110deg,
    color-mix(in oklab, var(--foreground) 5%, transparent),
    transparent 42%,
    color-mix(in oklab, var(--foreground) 3%, transparent)
  );
}

.course-cover-fade {
  background: linear-gradient(to bottom, transparent, var(--course-canvas, var(--background)));
}

.learner-course-intro::before {
  display: none;
  content: none;
}

.learner-course-shell > main {
  --course-canvas: var(--background);
  --course-canvas-strong: color-mix(in oklab, var(--background) 96%, var(--foreground) 4%);
  --course-selection: color-mix(in oklab, var(--background) 93%, var(--foreground) 7%);
}

.learner-course-shell .content-editor[data-mode="reader"] {
  --course-canvas: var(--background);
  --course-canvas-strong: color-mix(in oklab, var(--background) 96%, var(--foreground) 4%);
  --course-selection: color-mix(in oklab, var(--background) 93%, var(--foreground) 7%);
}

.learner-reader-with-shell .content-prose > h1[data-type="title"],
.learner-reader-with-shell .content-prose > p[data-type="description"] {
  display: none;
}

.learner-reader-with-shell .content-prose > :is(h1, h2, h3)[data-block-id] {
  scroll-margin-top: 7.5rem;
}

.learner-reader-with-shell .content-prose > h2[data-block-id] {
  margin-top: clamp(1.5rem, 2vw, 2rem);
  margin-bottom: 1.15rem;
  font-size: clamp(1.55rem, 2vw, 1.85rem);
  font-weight: 650;
  line-height: 1.18;
  letter-spacing: -0.025em;
}

@media (max-width: 640px) {
  .learner-reader-with-shell .content-prose > h2[data-block-id] {
    margin-bottom: 0.9rem;
    font-size: 1.5rem;
  }
}

.learner-course-shell {
  --learner-font-family: var(--font-cal-sans, ui-sans-serif), system-ui, sans-serif;
  --learner-prose-geometry: 0;
  --learner-control-geometry: 0;
  --learner-heading-geometry: 32;
  --learner-reading-measure: 72ch;
  font-family: var(--learner-font-family);
  font-variation-settings: "GEOM" var(--learner-prose-geometry);
}

.learner-course-shell :is(h1, h2, h3, h4, h5, h6) {
  font-family: var(--learner-font-family);
  font-variation-settings: "GEOM" var(--learner-heading-geometry);
}

.learner-course-shell :is(button, input, textarea, select, [data-slot="button"]) {
  font-family: var(--learner-font-family);
  font-variation-settings: "GEOM" var(--learner-control-geometry);
}

.learner-reader-with-shell .content-editor[data-mode="reader"] .content-prose {
  font-family: var(--learner-font-family);
  font-variation-settings: "GEOM" var(--learner-prose-geometry);
}

.learner-reader-with-shell
  .content-editor[data-mode="reader"]
  .content-prose
  > :is(p, ul, ol, blockquote) {
  width: min(100%, var(--learner-reading-measure));
  max-width: var(--learner-reading-measure);
}

/* Learner orientation keeps one editorial hierarchy: imagery establishes
   identity, while progress and actions remain semantic product controls. */
.learner-home-flow {
  display: flex;
  flex-direction: column;
  gap: clamp(2.5rem, 6vw, 5rem);
}

.learner-home-eyebrow {
  margin-bottom: 0.75rem;
  color: var(--muted-foreground);
  font-weight: 600;
  font-size: var(--learner-label-size);
  line-height: var(--learner-label-line);
  letter-spacing: normal;
  text-transform: none;
}

.learner-home-primary {
  display: grid;
  overflow: hidden;
  border: 1px solid color-mix(in oklab, var(--foreground) 10%, transparent);
  border-radius: 1.25rem;
  background: var(--background);
}

.learner-home-primary-cover,
.learner-course-home-cover {
  position: relative;
  min-height: 12rem;
  aspect-ratio: 16 / 10;
  overflow: hidden;
  background: var(--muted);
}

.learner-home-primary-copy {
  display: flex;
  min-width: 0;
  flex-direction: column;
  align-items: flex-start;
  justify-content: center;
  padding: clamp(1.5rem, 4vw, 3.25rem);
}

.learner-home-primary-copy > p:first-child,
.learner-home-course-publisher,
.learner-course-home-publisher {
  color: var(--muted-foreground);
  font-size: 0.75rem;
}

.learner-home-primary-copy h2 {
  max-width: 22ch;
  margin-top: 0.35rem;
  font-family: var(--font-cal-sans, ui-sans-serif), system-ui, sans-serif;
  font-size: clamp(1.8rem, 5vw, 3.25rem);
  line-height: 1.02;
  letter-spacing: -0.04em;
  overflow-wrap: anywhere;
}

.learner-home-primary-copy h2 + p {
  display: -webkit-box;
  max-width: 58ch;
  margin-top: 1rem;
  overflow: hidden;
  color: var(--muted-foreground);
  line-height: 1.65;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 3;
}

.learner-home-progress {
  width: min(100%, 30rem);
  margin-block: 1.5rem;
}

.learner-home-progress > span {
  display: block;
  margin-top: 0.5rem;
  color: var(--muted-foreground);
  font-size: 0.75rem;
}

.learner-home-section-title,
.learner-journey-title {
  margin-bottom: 1rem;
  font-family: var(--font-cal-sans, ui-sans-serif), system-ui, sans-serif;
  font-weight: 600;
  font-size: clamp(1.25rem, 3vw, 1.75rem);
  letter-spacing: -0.025em;
}

.learner-home-active-list,
.learner-home-completed-list {
  display: flex;
  flex-direction: column;
  border-top: 1px solid var(--border);
}

.learner-home-active-course,
.learner-home-completed-course {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 1rem;
  padding-block: 1rem;
  border-bottom: 1px solid var(--border);
}

.learner-home-active-cover {
  width: 6.5rem;
  aspect-ratio: 16 / 10;
  flex: none;
  overflow: hidden;
  border-radius: 0.5rem;
  background: var(--muted);
}

.learner-home-active-course h3,
.learner-home-completed-course h3 {
  font-weight: 600;
  overflow-wrap: anywhere;
}

.learner-home-active-course .learner-home-progress {
  max-width: 20rem;
  margin-block: 0.65rem 0;
}

.learner-home-completed-course > div > p,
.learner-home-completed-course > div > span {
  color: var(--muted-foreground);
  font-size: 0.75rem;
}

.learner-home-complete-mark {
  display: grid;
  width: 2rem;
  height: 2rem;
  flex: none;
  place-items: center;
  border: 1px solid var(--border);
  border-radius: 999px;
}

.learner-home-complete-mark svg {
  width: 0.9rem;
  height: 0.9rem;
}

button.learner-completion-marker {
  width: 2.75rem;
  height: 2.75rem;
  border-color: transparent;
  background: transparent;
  box-shadow: none;
}

button.learner-completion-marker::before {
  inset: 0.8125rem;
  border: 1px solid var(--input);
  background: var(--background);
}

button.learner-completion-marker > [data-slot="checkbox-indicator"] {
  inset: 0.8125rem;
}

.learner-home-empty {
  display: grid;
  min-height: 22rem;
  place-items: center;
  align-content: center;
  padding: 2rem;
  border: 1px solid var(--border);
  border-radius: 1rem;
  text-align: center;
}

.learner-home-empty > svg {
  width: 2rem;
  height: 2rem;
  margin-bottom: 1rem;
  color: var(--muted-foreground);
}

.learner-home-empty h2 {
  font-family: var(--font-cal-sans, ui-sans-serif), system-ui, sans-serif;
  font-weight: 600;
  font-size: 1.5rem;
}

.learner-home-empty > p:last-of-type {
  max-width: 34rem;
  margin-block: 0.5rem 1.25rem;
  color: var(--muted-foreground);
}

.learner-course-home {
  min-height: 100dvh;
  padding: clamp(1rem, 4vw, 3.5rem);
  background: var(--background);
}

.learner-course-home-hero,
.learner-course-home-grid {
  width: min(100%, 80rem);
  margin-inline: auto;
}

.learner-course-home-hero {
  display: grid;
  overflow: hidden;
  border: 1px solid color-mix(in oklab, var(--foreground) 10%, transparent);
  border-radius: 1.25rem;
}

.learner-course-home-copy {
  display: flex;
  min-width: 0;
  flex-direction: column;
  align-items: flex-start;
  justify-content: center;
  padding: clamp(1.5rem, 4vw, 3.5rem);
}

.learner-course-home-copy h1 {
  max-width: 20ch;
  margin-top: 0.45rem;
  font-family: var(--font-cal-sans, ui-sans-serif), system-ui, sans-serif;
  font-weight: 600;
  font-size: clamp(2rem, 5vw, 4rem);
  line-height: 0.98;
  letter-spacing: -0.045em;
  overflow-wrap: anywhere;
}

.learner-course-home-description {
  max-width: 58ch;
  margin-top: 1rem;
  color: var(--muted-foreground);
  font-size: 1rem;
  line-height: 1.65;
}

.learner-course-home-progress {
  width: min(100%, 32rem);
  margin-top: 1.75rem;
}

.learner-course-home-progress > div {
  display: flex;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: 0.5rem;
  color: var(--muted-foreground);
  font-size: 0.75rem;
}

.learner-course-home-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.625rem 1rem;
  margin-top: 1.5rem;
}

.learner-course-home-primary-action,
.learner-course-home-secondary-actions {
  display: flex;
  align-items: center;
}

.learner-course-home-secondary-actions {
  flex-wrap: wrap;
  gap: 0.25rem;
}

.learner-course-home-grid {
  display: grid;
  gap: clamp(2rem, 5vw, 4rem);
  padding-block: clamp(2.5rem, 6vw, 5rem);
}

.learner-journey-list {
  display: flex;
  flex-direction: column;
  border-top: 1px solid var(--border);
}

.learner-journey-list > li {
  border-bottom: 1px solid var(--border);
}

.learner-journey-item {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 0.9rem;
  padding: 1rem 0.75rem;
}

.learner-journey-link {
  border-radius: 0.35rem;
  outline: none;
  transition: background-color 120ms ease;
}

.learner-journey-link:hover {
  background: color-mix(in oklab, var(--foreground) 4%, transparent);
}

.learner-journey-link:focus-visible {
  box-shadow: 0 0 0 2px var(--ring);
}

.learner-journey-icon {
  display: grid;
  width: 2rem;
  height: 2rem;
  flex: none;
  place-items: center;
  border: 1px solid var(--border);
  border-radius: 999px;
}

.learner-journey-icon svg {
  width: 0.9rem;
  height: 0.9rem;
}

[data-journey-state="current"] .learner-journey-icon {
  border-color: var(--course-accent, var(--primary));
  background: var(--course-accent, var(--primary));
  color: var(--primary-foreground);
}

[data-journey-state="locked"] .learner-journey-item {
  color: var(--muted-foreground);
}

.learner-journey-copy {
  display: flex;
  min-width: 0;
  flex: 1;
  flex-direction: column;
}

.learner-journey-name {
  font-weight: 500;
}

.learner-journey-meta {
  margin-top: 0.2rem;
  color: var(--muted-foreground);
  font-size: 0.75rem;
}

.learner-course-home-cohort {
  align-self: start;
  padding: 1.25rem;
  border: 1px solid var(--border);
  border-radius: 0.75rem;
  background: color-mix(in oklab, var(--background) 97%, var(--foreground) 3%);
}

@media (min-width: 768px) {
  .learner-home-primary,
  .learner-course-home-hero {
    grid-template-columns: minmax(17rem, 0.85fr) minmax(0, 1.15fr);
  }

  .learner-home-primary-cover,
  .learner-course-home-cover {
    min-height: 100%;
    aspect-ratio: auto;
  }
}

@media (min-width: 1024px) {
  .learner-course-home-grid:has(.learner-course-home-cohort) {
    grid-template-columns: minmax(0, 1fr) 20rem;
  }
}

@media (max-width: 560px) {
  .learner-home-active-course,
  .learner-home-completed-course {
    align-items: flex-start;
    flex-wrap: wrap;
  }

  .learner-home-active-course > [data-slot="button"],
  .learner-home-completed-course > div:last-child {
    width: 100%;
  }

  .learner-home-active-course > [data-slot="button"] {
    justify-content: center;
  }

  .learner-course-home-actions {
    width: 100%;
    flex-direction: column;
    align-items: stretch;
  }

  .learner-course-home-primary-action,
  .learner-course-home-primary-action > [data-slot="button"] {
    width: 100%;
  }

  .learner-course-home-secondary-actions {
    justify-content: flex-start;
  }
}

@media (prefers-reduced-motion: reduce) {
  .learner-journey-link {
    transition: none;
  }
}

@media (forced-colors: active) {
  .learner-home-primary,
  .learner-course-home-hero,
  .learner-home-complete-mark,
  .learner-journey-icon {
    border-color: CanvasText;
  }

  [data-journey-state="current"] .learner-journey-icon {
    background: Highlight;
    color: HighlightText;
  }
}

.learner-study-frame {
  min-width: 0;
}

.learner-study-tool-rail {
  position: sticky;
  top: 0;
  height: 100dvh;
  overflow: hidden;
  border-left: 1px solid var(--border);
  background: var(--background);
}

.learner-study-tool-rail > header {
  display: flex;
  min-height: 3.5rem;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding-inline: 1.25rem;
  border-bottom: 1px solid var(--border);
}

.learner-study-tool-rail > header h2 {
  font-family: var(--font-cal-sans, ui-sans-serif), system-ui, sans-serif;
  font-weight: 600;
  font-size: 1rem;
}

.learner-study-tool-rail-body {
  height: calc(100dvh - 3.5rem);
  overflow-y: auto;
  padding: 1.25rem;
}

@media (min-width: 1536px) {
  .learner-study-frame[data-context-tool-open="true"] {
    display: grid;
    grid-template-columns: minmax(0, 1fr) 26rem;
    align-items: start;
  }
}

@media (forced-colors: active) {
  .learner-study-tool-rail {
    border-left-color: CanvasText;
  }
}

